function src_regions_create() {

db_query("DROP TABLE IF EXISTS src_region_types");
db_query(
"CREATE TABLE src_region_types (
  type__full varchar(512) not null primary key,
  type__abr varchar(128) not null,
  type__src varchar(256) not null,
  type__region varchar(256) not null
)
");

db_query("DROP TABLE IF EXISTS src_old_regions");
db_query(
"CREATE TABLE src_old_regions (
  regi__id int not null primary key,
  new__id int null,
  regi__type enum('CONTINENT','COUNTRY','REGION','APPELLATION') NULL,
  regi__weight smallint NULL default 0,
  regi__level smallint NULL default 0,
  regi__name varchar(255) NULL,
  to_name varchar(255) NULL default '',
  child__ids varchar(4096) NULL default '',
  gwe__ids varchar(4096) NULL default '',
  is_new tinyint NULL default 0,
  Country varchar(255) NULL
)
");
db_query("DROP TABLE IF EXISTS `src_countries`");
db_query(
"CREATE TABLE `src_countries` (
  `country__tid` int(10) unsigned NOT NULL,
  `country__name` varchar(2048) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
");
