  `src_path` varchar(1024) DEFAULT NULL,
  `to_name` varchar(256) DEFAULT NULL,
  `to_path` varchar(256) DEFAULT NULL,
  `to_path__id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
)
");
